/**
 * Neo4j persistence of an Application's structure (one :RtApplication root + one :Rt<Tag> node
 * per top-level child, each carrying its own element's verbatim XML — see the plan's storage
 * design). Pure plumbing: reuses runtime/neo4jStore.ts's withTx/neo4jSession directly, zero
 * vocabulary coupling on that side. `applicationId` here is the OWNING Postgres
 * runtime_applications row's id — created by the route before this is ever called — never
 * generated by this module itself, so Postgres stays the one ownership source of truth.
 */
import type { Transaction } from "neo4j-driver";
import { withTx, neo4jSession } from "../runtime/neo4jStore.js";
import { toDriverValue, fromDriverValue } from "../runtime/values.js";
import { HttpError } from "../services/authService.js";
import {
  parseApplicationXml, parseEntityElement, parseRelationshipElement, parseScreenElement,
  parseValidationElement, parseActionElement, parseDataSourceElement, type ParsedTopLevelElement,
} from "./applicationModel.js";

export type ApplicationElementRow = { tag: string; name: string; xml: string; position: number };
export type ApplicationDetail = { name: string; theme: string | null; database: string | null; elements: ApplicationElementRow[] };

const KNOWN_TAGS = new Set([
  "Theme", "Session", "Auditing", "AutoNumber", "Entity", "Relationship", "Validation", "DataSource", "Screen", "Action",
]);

// Same shape as projectStore.ts's own (private) guard() — a Neo4j connection failure should
// surface as a clean, generic 503, never the raw driver error (routing-table internals, etc.)
// leaking straight to the client. Exported too, so routes/runtimeApplications.ts's own direct
// withTx call (for running a Screen's action) gets the same treatment.
export async function guard<T>(fn: () => Promise<T>): Promise<T> {
  try {
    return await fn();
  } catch (e) {
    if (e instanceof HttpError) throw e;
    console.error("Runtime Engine (Neo4j) operation failed:", e instanceof Error ? e.message : e);
    throw new HttpError(503, "Workspace database unavailable — please try again shortly.");
  }
}

function assertKnownTag(tag: string): void {
  if (!KNOWN_TAGS.has(tag)) throw new Error(`Unknown top-level Application element <${tag}> — expected one of ${[...KNOWN_TAGS].join(", ")}`);
}

// Caught live: the AI once added extra required fields (an account code, a role link) straight
// onto an isAccount Entity "to model RBAC" — every signup then failed with "X is required" since
// the login/register built-ins only ever set id/username/passwordHash/mustChangePassword (see
// applicationEngine.ts). Enforced here, at save time, rather than only discovered at first
// signup — the whole point of validating deterministically before anything is stored.
const USER_ACCOUNT_FIELDS = new Set(["id", "username", "passwordHash", "mustChangePassword"]);
function assertAccountEntityShape(el: ParsedTopLevelElement): void {
  if (el.tag !== "Entity") return;
  const entity = parseEntityElement(el.xml);
  if (!entity.isAccount) return;
  const names = entity.fields.map((f) => f.name);
  const extra = names.filter((n) => !USER_ACCOUNT_FIELDS.has(n));
  const missing = [...USER_ACCOUNT_FIELDS].filter((n) => !names.includes(n));
  if (extra.length || missing.length) {
    throw new Error(
      `Entity "${entity.name}" is marked isAccount="true" but its fields don't match the fixed ` +
        `convention (id, username, passwordHash, mustChangePassword) — ` +
        `${extra.length ? `extra field(s): ${extra.join(", ")}` : ""}${extra.length && missing.length ? "; " : ""}` +
        `${missing.length ? `missing field(s): ${missing.join(", ")}` : ""}. ` +
        `Link any role/employee/etc. via a Relationship pointing AT this entity instead of adding a field to it.`
    );
  }
}

// Built-ins have fixed runtime semantics and are never a named Action to link to — same set
// applicationEngine.ts's BUILTIN_ACTIONS defines, duplicated rather than imported (a tiny literal
// list, same tradeoff as pluralizeCamel elsewhere in this engine).
const BUILTIN_BUTTON_ACTIONS = new Set(["save", "cancel", "delete", "openRecord", "login", "register", "changePassword"]);

function dsNameOf(ref: string | null): string | null {
  return ref ? ref.replace(/^query:/, "") : null;
}

// The structural graph itself, beyond the flat RtApplication-[:CONTAINS]->child star: Entities
// connected to each other via their Relationships, and every other element connected to the
// Entity/DataSource/Action/Screen it actually references — "each screen should be connected to
// [its entity's] node, and like this it all should be connected," not just independently hanging
// off one central hub. Purely structural/for introspection — execution still re-parses each
// element's own stored XML (applicationEngine.ts et al.), never traverses these edges; that path
// is already proven and stays untouched.
async function linkElements(tx: Transaction, applicationId: number, manifest: { elements: ParsedTopLevelElement[] }): Promise<void> {
  const id = toDriverValue(applicationId);
  const forEntity = async (fromTag: string, fromName: string, entityName: string | null) => {
    if (!entityName) return;
    await tx.run(
      `MATCH (a:RtApplication {applicationId: $id})-[:CONTAINS]->(from:${fromTag} {applicationId: $id, name: $fromName}) ` +
        `MATCH (a)-[:CONTAINS]->(e:Entity {applicationId: $id, name: $entityName}) ` +
        "MERGE (from)-[:FOR_ENTITY]->(e)",
      { id, fromName, entityName }
    );
  };

  for (const el of manifest.elements) {
    if (el.tag === "Relationship") {
      const rel = parseRelationshipElement(el.xml);
      await tx.run(
        `MATCH (a:RtApplication {applicationId: $id})-[:CONTAINS]->(r:Relationship {applicationId: $id, name: $relName}) ` +
          `MATCH (a)-[:CONTAINS]->(from:Entity {applicationId: $id, name: $fromEntity}) ` +
          `MATCH (a)-[:CONTAINS]->(to:Entity {applicationId: $id, name: $toEntity}) ` +
          "MERGE (r)-[:FROM_ENTITY]->(from) MERGE (r)-[:TO_ENTITY]->(to)",
        { id, relName: el.name, fromEntity: rel.fromEntity, toEntity: rel.toEntity }
      );
    } else if (el.tag === "Validation") {
      await forEntity("Validation", el.name, parseValidationElement(el.xml).entity);
    } else if (el.tag === "Action") {
      await forEntity("Action", el.name, parseActionElement(el.xml).entity);
    } else if (el.tag === "DataSource") {
      await forEntity("DataSource", el.name, parseDataSourceElement(el.xml).entity);
    } else if (el.tag === "Screen") {
      const screen = parseScreenElement(el.xml);
      await forEntity("Screen", el.name, screen.entity);

      const dsNames = new Set<string>();
      for (const f of screen.fields) {
        const name = dsNameOf(f.optionsFrom);
        if (name) dsNames.add(name);
      }
      const gridDsName = dsNameOf(screen.grid?.rowsFrom ?? null);
      if (gridDsName) dsNames.add(gridDsName);
      for (const dsName of dsNames) {
        await tx.run(
          `MATCH (a:RtApplication {applicationId: $id})-[:CONTAINS]->(s:Screen {applicationId: $id, name: $sName}) ` +
            `MATCH (a)-[:CONTAINS]->(d:DataSource {applicationId: $id, name: $dsName}) ` +
            "MERGE (s)-[:USES_DATASOURCE]->(d)",
          { id, sName: el.name, dsName }
        );
      }

      const actionNames = new Set(screen.buttons.map((b) => b.action).filter((a) => !BUILTIN_BUTTON_ACTIONS.has(a)));
      for (const actionName of actionNames) {
        await tx.run(
          `MATCH (a:RtApplication {applicationId: $id})-[:CONTAINS]->(s:Screen {applicationId: $id, name: $sName}) ` +
            `MATCH (a)-[:CONTAINS]->(act:Action {applicationId: $id, name: $actionName}) ` +
            "MERGE (s)-[:RUNS_ACTION]->(act)",
          { id, sName: el.name, actionName }
        );
      }

      const targetScreens = new Set((screen.grid?.onEvents ?? []).map((e) => e.targetScreen).filter((t): t is string => !!t));
      for (const targetScreen of targetScreens) {
        await tx.run(
          `MATCH (a:RtApplication {applicationId: $id})-[:CONTAINS]->(s:Screen {applicationId: $id, name: $sName}) ` +
            `MATCH (a)-[:CONTAINS]->(t:Screen {applicationId: $id, name: $targetScreen}) ` +
            "MERGE (s)-[:OPENS_SCREEN]->(t)",
          { id, sName: el.name, targetScreen }
        );
      }
    }
  }
}

// Replaces this Application's whole node set — same "full replace, no partial patch" semantics
// the old engine's replaceAllRows already uses for a bulk grid save; there's no meaningful partial
// update of an Application's structure, only "here is the new XML, make the graph match it."
export async function saveApplicationNodes(
  applicationId: number, xml: string
): Promise<{ name: string; theme: string | null; database: string | null; elementCounts: Record<string, number> }> {
  // Parsing/validation failures are the CALLER's XML being wrong, not a server problem — a clean
  // 400 with the real reason, never the generic 500 an unconverted plain Error would otherwise
  // surface as once it reaches the central error handler.
  let manifest: ReturnType<typeof parseApplicationXml>;
  try {
    manifest = parseApplicationXml(xml);
    for (const el of manifest.elements) {
      assertKnownTag(el.tag);
      assertAccountEntityShape(el);
    }
  } catch (e) {
    throw new HttpError(400, e instanceof Error ? e.message : String(e));
  }

  await guard(() =>
    withTx(async (tx) => {
      await tx.run("MATCH (a:RtApplication {applicationId: $id}) OPTIONAL MATCH (a)-[:CONTAINS]->(child) DETACH DELETE a, child", {
        id: toDriverValue(applicationId),
      });
      await tx.run(
        "CREATE (a:RtApplication {applicationId: $id, name: $name, theme: $theme, database: $database, createdAt: $now, updatedAt: $now})",
        { id: toDriverValue(applicationId), name: manifest.name, theme: manifest.theme, database: manifest.database, now: new Date().toISOString() }
      );
      for (const el of manifest.elements) {
        await tx.run(
          `CREATE (child:${el.tag} {applicationId: $id, name: $name, xml: $xml, position: $position, createdAt: $now}) ` +
            "WITH child MATCH (a:RtApplication {applicationId: $id}) CREATE (a)-[:CONTAINS]->(child)",
          { id: toDriverValue(applicationId), name: el.name, xml: el.xml, position: toDriverValue(el.position), now: new Date().toISOString() }
        );
      }
      await linkElements(tx, applicationId, manifest);
    })
  );

  const elementCounts: Record<string, number> = {};
  for (const el of manifest.elements) elementCounts[el.tag] = (elementCounts[el.tag] || 0) + 1;
  return { name: manifest.name, theme: manifest.theme, database: manifest.database, elementCounts };
}

export async function getApplication(applicationId: number): Promise<ApplicationDetail | null> {
  return guard(async () => {
    const session = neo4jSession();
    try {
      const res = await session.run(
        "MATCH (a:RtApplication {applicationId: $id}) OPTIONAL MATCH (a)-[:CONTAINS]->(child) " +
          "RETURN a.name AS name, a.theme AS theme, a.database AS database, " +
          "collect(CASE WHEN child IS NULL THEN NULL ELSE {tag: labels(child)[0], name: child.name, xml: child.xml, position: child.position} END) AS elements",
        { id: toDriverValue(applicationId) }
      );
      const record = res.records[0];
      if (!record) return null;
      const rawElements = (fromDriverValue(record.get("elements")) as (ApplicationElementRow | null)[]).filter(
        (e): e is ApplicationElementRow => e !== null
      );
      rawElements.sort((a, b) => a.position - b.position);
      return { name: record.get("name"), theme: record.get("theme"), database: record.get("database"), elements: rawElements };
    } finally {
      await session.close();
    }
  });
}

export async function listApplicationSummaries(applicationIds: number[]): Promise<Map<number, { name: string; theme: string | null; database: string | null; elementCounts: Record<string, number> }>> {
  const out = new Map<number, { name: string; theme: string | null; database: string | null; elementCounts: Record<string, number> }>();
  if (!applicationIds.length) return out;
  return guard(async () => {
    const session = neo4jSession();
    try {
      const res = await session.run(
        "MATCH (a:RtApplication) WHERE a.applicationId IN $ids OPTIONAL MATCH (a)-[:CONTAINS]->(child) " +
          "RETURN a.applicationId AS applicationId, a.name AS name, a.theme AS theme, a.database AS database, labels(child) AS childLabels",
        { ids: applicationIds.map(toDriverValue) }
      );
      for (const record of res.records) {
        const id = Number(fromDriverValue(record.get("applicationId")));
        const entry = out.get(id) || { name: record.get("name"), theme: record.get("theme"), database: record.get("database"), elementCounts: {} as Record<string, number> };
        const childLabels = (record.get("childLabels") as string[] | null) || [];
        for (const tag of childLabels) {
          if (tag === "RtApplication") continue;
          entry.elementCounts[tag] = (entry.elementCounts[tag] || 0) + 1;
        }
        out.set(id, entry);
      }
      return out;
    } finally {
      await session.close();
    }
  });
}

export async function getElementXml(applicationId: number, tag: string, name: string): Promise<string | null> {
  assertKnownTag(tag);
  return guard(async () => {
    const session = neo4jSession();
    try {
      const res = await session.run(`MATCH (a:RtApplication {applicationId: $id})-[:CONTAINS]->(child:${tag} {name: $name}) RETURN child.xml AS xml`, {
        id: toDriverValue(applicationId), name,
      });
      return res.records[0] ? (res.records[0].get("xml") as string) : null;
    } finally {
      await session.close();
    }
  });
}

export async function deleteApplicationNodes(applicationId: number): Promise<void> {
  await guard(() =>
    withTx(async (tx) => {
      await tx.run("MATCH (a:RtApplication {applicationId: $id}) OPTIONAL MATCH (a)-[:CONTAINS]->(child) DETACH DELETE a, child", {
        id: toDriverValue(applicationId),
      });
    })
  );
}

export type { ParsedTopLevelElement };
